ORDER BY (USED_LIMIT / TOTAL_LIMIT) DESC

mapper.update:
UPDATE TBL_CREDIT_LIMIT 
SET FROZEN_LIMIT = FROZEN_LIMIT + #{freezeAmount},
    AVAILABLE_LIMIT = AVAILABLE_LIMIT - #{freezeAmount},
    UPDATETIME = CURRENT_TIMESTAMP
WHERE ID = #{limitId}
AND AVAILABLE_LIMIT >= #{freezeAmount}

UPDATE TBL_CREDIT_LIMIT 
SET FROZEN_LIMIT = FROZEN_LIMIT - #{unfreezeAmount},
    AVAILABLE_LIMIT = AVAILABLE_LIMIT + #{unfreezeAmount},
    UPDATETIME = CURRENT_TIMESTAMP
WHERE ID = #{limitId}
AND FROZEN_LIMIT >= #{unfreezeAmount}

