WHERE COMPANY_ID = #{companyId}
AND AVAILABLE_LIMIT >= #{minAmount}
AND LIMIT_STATUS = 'ACTIVE'
AND EXPIRY_DATE > CURRENT_DATE

    AND CREDIT_TYPE = #{creditType}


    AND ORGID = #{orgId}

